import random
import itertools
import json
from reduce import reduce
from problems import VertexCover, Clique


def solve_vertex_cover(instance):
    n = instance["n"]
    edges = [tuple(e) for e in instance["edges"]]
    k = instance["k"]
    if k < 0:
        return False
    # trivial yes cases
    if not edges:
        return True
    if k >= n:
        return True
    vertices = list(range(n))
    for r in range(k + 1):
        for subset in itertools.combinations(vertices, r):
            covered = set()
            for u, v in edges:
                if u in subset or v in subset:
                    covered.add((u, v))
            if len(covered) == len(edges):
                return True
    return False


def solve_clique(instance):
    n = instance["n"]
    edges_set = {tuple(sorted(e)) for e in instance["edges"]}
    k = instance["k"]
    if k <= 0:
        return True
    if n == 0:
        return k <= 0
    if k == 1:
        return n >= 1
    if k > n:
        return False
    vertices = list(range(n))
    # check all subsets of size >=k
    for size in range(k, n + 1):
        for subset in itertools.combinations(vertices, size):
            ok = True
            for u, v in itertools.combinations(subset, 2):
                if tuple(sorted((u, v))) not in edges_set:
                    ok = False
                    break
            if ok:
                return True
    return False


