    possible = [(u, v) for u in range(n) for v in range(u + 1, n)]
    edges = []
    for (u, v) in possible:
        if random.choice([True, False]):
            edges.append([u, v])
    k = random.randint(-1, n + 1)
    return {"n": n, "edges": edges, "k": k}


def main():
    tests = 200
    passed = 0
    for i in range(tests):
        src = random_instance()
        # validate source
        VertexCover.validate(src)
        tgt = reduce(src)
        Clique.validate(tgt)
        ans_src = solve_vertex_cover(src)
        ans_tgt = solve_clique(tgt)
        if ans_src == ans_tgt:
            passed += 1
        else:
            print("Mismatch on test", i)
            print("src", src)
            print("tgt", tgt)
            print("src ans", ans_src, "tgt ans", ans_tgt)
            break
    verdict = {"verified": passed == tests, "tests_run": tests, "tests_passed": passed}
    with open('verdict.json', 'w') as f:
        json.dump(verdict, f)
    print(json.dumps(verdict))

if __name__ == '__main__':
